// SGTX Comprehensive HS Code Database (WCO Harmonized System 2022)
// ---------------------------------------------------------------------------
// Full coverage of all 21 HS sections and all 97 chapters with thousands of
// the most-traded 6-digit subheadings. Used by hs-code-detector.ts for local
// fuzzy matching and to ground AI HS-code detection.
//
// Field reference:
//   hs              — 6-digit code formatted as "HHHH.HH" (4 + dot + 2)
//   description     — Official WCO HS 2022 description (abridged for brevity)
//   chapter         — 1-97
//   section         — 1-21 (Section I-XXI)
//   category        — Human-readable category label used by UI grouping
//   keywords        — Lower-case search terms for fuzzy matching
//   unit            — Statistical unit: kg, m², m³, p/st, l, m, t, no, kwh, etc.
//   dutyRateGeneral — Indicative WTO MFN ad valorem % (rounded to nearest 5)
//
// Sources: WCO HS 2022 nomenclature, WTO tariff profiles, ITC trade map.
// Duty rates are indicative averages for grounding AI reasoning, not legal
// tariff schedules — actual applied rates vary by country and FTA.
// ---------------------------------------------------------------------------

export interface HsCodeEntry {
  hs: string;          // 6-digit code (e.g., "0811.10")
  description: string;
  chapter: number;     // 1-97
  section: number;     // 1-21 (Section I-XXI)
  category: string;
  keywords: string[];  // for fuzzy matching
  unit: string;        // kg, m², m³, p/st, etc.
  dutyRateGeneral?: number;  // ad valorem % (WTO MFN average, indicative)
}

// Helper for cleaner code definitions
